ROWS = [
 ("A5.006", "targeted proof check", "checked: on A^1 over C with T_n = {n}, every positive-dimensional locally closed algebraic subset is cofinite and so contains infinitely many integers, hence an adapted partition with algebraic leaves has singleton leaves, which is not locally finite in the classical topology; for finite definable partitions X = R with the same family needs infinitely many leaves; the scope remarks (Zariski local finiteness, analytic leaves) are right"),
 ("A5.008", "targeted proof check (Coste 1999 Hardt cited)", "read in full: the union U_0 of open members of a frontier refinement of a Hardt partition is a dense open manifold locus of local triviality, so the maximal U exists with nowhere dense complement; for dim Y <= 1 the complement of U_0 is finite and U is definable; for a finite simplicial map, barycentric rescaling lifted to the source gives simultaneous homeomorphisms along each open target simplex, so U is a finite union of open simplices; the caveat that Hardt alone does not identify U is right"),
]
